def gen(rng):
    def make(n, mode):
        left = [-1] * n
        right = [-1] * n
        depth = [0] * n
        slots = [(0, 0), (0, 1)]
        for v in range(1, n):
            if mode == 'chain':
                u, s = v - 1, rng.randint(0, 1)
            elif mode == 'left':
                u, s = v - 1, 0
            else:
                j = rng.randrange(len(slots))
                slots[j], slots[-1] = slots[-1], slots[j]
                u, s = slots.pop()
            if s == 0:
                left[u] = v
            else:
                right[u] = v
            depth[v] = depth[u] + 1
            slots.append((v, 0))
            slots.append((v, 1))
        return left, right
    def to_level(n, left, right):
        q = [0]
        h = 0
        vals = [rng.randint(-100, 100) for _ in range(n)]
        while h < len(q):
            u = q[h]
            h += 1
            for c in (left[u], right[u]):
                if c != -1:
                    q.append(c)
        # token list: root, then for each dequeued node its two children
        toks = [str(vals[0])]
        h = 0
        while h < len(q):
            u = q[h]
            h += 1
            for c in (left[u], right[u]):
                toks.append('null' if c == -1 else str(vals[c]))
        while toks and toks[-1] == 'null':
            toks.pop()
        return ' '.join(toks)
    def rand_tree(n, mode='rand'):
        l, r = make(n, mode)
        return to_level(n, l, r)
    tests = [
        '5',
        '1 2',
        '1 null 2',
        '1 2 3',
        '3 9 20 null null 15 7',
        '1 2 null 3 null 4',
        '1 null 2 null 3 null 4 null 5',
        '7 7 7 7 7 7 7',
    ]
    for n in (2, 3, 4, 5, 6, 7, 9, 12, 15):
        for _ in range(3):
            tests.append(rand_tree(n))
    for n in (5, 8, 20):
        tests.append(rand_tree(n, 'chain'))
        tests.append(rand_tree(n, 'left'))
    tests.append(rand_tree(100000))
    tests.append(rand_tree(100000))
    # deep chain of 5000 nodes followed by random growth near the top of the structure
    n = 100000
    left2 = [-1] * n
    right2 = [-1] * n
    for v in range(1, 5000):
        if rng.randint(0, 1):
            left2[v - 1] = v
        else:
            right2[v - 1] = v
    slots = [(v, s) for v in range(0, 5000) for s in (0, 1) if (left2[v] == -1 if s == 0 else right2[v] == -1)]
    # attach the rest only below nodes 0..200 so the depth stays below 5000
    slots = [(v, s) for (v, s) in slots if v < 200]
    for v in range(5000, n):
        j = rng.randrange(len(slots))
        slots[j], slots[-1] = slots[-1], slots[j]
        u, s = slots.pop()
        if s == 0:
            left2[u] = v
        else:
            right2[u] = v
        slots.append((v, 0))
        slots.append((v, 1))
    tests.append(to_level(n, left2, right2))
    # pure chain of exactly 5000 nodes
    tests.append(rand_tree(5000, 'chain'))
    return tests
